"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[13681],{84122:e=>{e.exports=JSON.parse('{"functions":[{"name":"Init","desc":"Initialises the notification system and must be called exactly once,\\nfrom `NotificationController.client.luau`.\\n\\nCalling `Init` more than once is a no-op.  On first call it:\\n- Resolves `Players.LocalPlayer` and `PlayerGui`.\\n- Creates the manager-level `Janitor` for top-level cleanup.\\n- Binds a debounced `ViewportSize` listener so toasts resize when the\\n  window or device orientation changes (re-binds if `CurrentCamera` is\\n  replaced).\\n- Connects `Signals.RequestNotification` \u2192 internal `show`.\\n- Connects `Signals.RequestClearNotifications` \u2192 internal `clearAll`.","params":[],"returns":[],"function_type":"static","source":{"line":524,"path":"src/ReplicatedStorage/SharedModules/NotificationManager/init.luau"}}],"properties":[],"types":[],"name":"NotificationManager","desc":"Displays signal-driven toast notifications in the client UI.\\n\\nCallers **do not** call methods on this module directly after\\ninitialisation.  Instead they fire signals:\\n\\n- `Signals.RequestNotification(notifType, message, duration?, executedFunction?)`\\n  \u2014 show a toast.\\n- `Signals.RequestClearNotifications()` \u2014 dismiss all active toasts.\\n\\n`Init` must be called once from `NotificationController.client.luau`.\\nAudio is delegated to `SoundManager`; animations use `MotionMaster`;\\nlifecycle cleanup uses `Janitor`.","realm":["Client"],"source":{"line":24,"path":"src/ReplicatedStorage/SharedModules/NotificationManager/init.luau"}}')}}]);